def max_pairwise_xor(nums):
    best = 0
    mask = 0
    for bit in range(31, -1, -1):
        mask |= 1 << bit
        prefixes = {n & mask for n in nums}
        candidate = best | (1 << bit)
        if any(p ^ candidate in prefixes for p in prefixes):
            best = candidate
    return best
